package app.clearscreen;

import org.json.JSONObject;
import java.util.*;
import java.util.regex.Pattern;

/** Port of upstream tool/channel_policy.py; patterns generated by tools/import_rules.py. */
public final class Policy {
    private static final Pattern CRITICAL_EN=Pattern.compile(
            "\\b(?:orders?|shipments?|deliveries|delivery|payments?|transactions?|verification|security|"
            +"weather alerts?|phone calls?|missed calls?|direct messages?|chat messages?|downloads?|app updates?|installations?)\\b",
            Pattern.CASE_INSENSITIVE);
    private final Map<String,Pattern> patterns=new HashMap<>();
    public Policy(JSONObject data){ for(String key:new String[]{"PHOTO_SPOT","KW","SKIP","VIVO_MARKETING","AD_NETWORK","SERVICE_TERMS","NEG_PREFIX"})patterns.put(key,Pattern.compile(data.optString(key),Pattern.CASE_INSENSITIVE|Pattern.UNICODE_CASE)); }
    boolean hit(String name,String value){return patterns.get(name).matcher(value).find();}
    public boolean desired(String title){return hit("NEG_PREFIX",title.trim());}
    public boolean protectedTitle(String title){return hit("PHOTO_SPOT",title.replaceAll("[\\s\u200b\ufeff]",""));}
    public boolean protectedSetting(String title){return protectedTitle(title)||title.matches(".*(天气预警|天氣預警|应用更新通知|應用更新通知|下载通知|下載通知|安装通知|安裝通知|订单通知|訂單通知|物流通知|支付通知|聊天消息|聊天訊息|私信通知|安全提醒|验证通知|驗證通知).*");}
    /** Additional mobile safeguard: never let an advertising SDK id override a critical channel title. */
    public boolean criticalNotification(String title){return title.matches(".*(订单|訂單|物流|快递|快遞|交易|支付|付款|验证|驗證|安全|天气预警|天氣預警|通话|通話|来电|來電|聊天|私信|下载|下載|更新|安装|安裝).*")||CRITICAL_EN.matcher(title).find();}
    public Decision classify(String name,String id,String pkg,String app){
        boolean vivo=hit("VIVO_MARKETING",id), ad=hit("AD_NETWORK",id);
        boolean protectedValue=protectedTitle(name+" "+id);
        boolean candidate=ad||hit("KW",name+" "+id);
        boolean excluded=hit("SKIP",name)&&!vivo&&!ad;
        boolean uncertain=hit("SERVICE_TERMS",String.join(" ",pkg,id,name,app))||"其他".equals(app.isEmpty()?name:app)||(pkg.toLowerCase(Locale.ROOT).endsWith("youtube")&&id.equals("2"));
        return new Decision(candidate,excluded,uncertain,protectedValue);
    }
    public static final class Decision {
        public final boolean candidate, excluded, uncertain, protectedValue;
        Decision(boolean a,boolean b,boolean c,boolean d){candidate=a;excluded=b;uncertain=c;protectedValue=d;}
        public boolean recommended(){return candidate&&!excluded&&!uncertain&&!protectedValue;}
    }
}
